const item = $input.first();
const payload = item.json.body || item.json;

const canal = payload.canal;
const contenido = payload.contenido;

if (!canal || !contenido) {
  throw new Error('Faltan campos requeridos: canal y contenido');
}

try {
  if (canal === 'whatsapp') {
    const evoUrl = process.env.EVOLUTION_API_URL || 'http://evolution-api:8080';
    const evoKey = process.env.EVOLUTION_API_KEY;
    const evoInstance = process.env.EVOLUTION_INSTANCE || 'romicars';
    await $helpers.httpRequest({
      method: 'POST',
      url: evoUrl + '/message/sendText/' + evoInstance,
      headers: { 'Content-Type': 'application/json', apikey: evoKey },
      body: { number: payload.telefono, text: contenido }
    });
  } else if (canal === 'facebook') {
    const pageToken = process.env.FB_PAGE_TOKEN;
    await $helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v22.0/me/messages?access_token=' + pageToken,
      headers: { 'Content-Type': 'application/json' },
      body: {
        messaging_type: 'RESPONSE',
        recipient: { id: payload.facebook_psid },
        message: { text: contenido }
      }
    });
  } else if (canal === 'instagram') {
    const pageToken = process.env.FB_PAGE_TOKEN;
    await $helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.facebook.com/v22.0/me/messages?access_token=' + pageToken,
      headers: { 'Content-Type': 'application/json' },
      body: {
        messaging_type: 'RESPONSE',
        recipient: { id: payload.instagram_psid },
        message: { text: contenido }
      }
    });
  } else {
    throw new Error('Canal no soportado: ' + canal);
  }

  return [{ json: { success: true, msg_id: payload.msg_id, canal: canal } }];
} catch (error) {
  return [{ json: { success: false, error: error.message, canal: canal } }];
}
